#include <openssl/evp.h>
#include <string.h>

int aesgcm_encrypt(const unsigned char *key, int keylen,
                   const unsigned char *nonce, int noncelen,
                   const unsigned char *aad, int aadlen,
                   const unsigned char *pt, long long ptlen,
                   unsigned char *out, unsigned char *tag)
{
    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) return -1;
    const EVP_CIPHER *cipher;
    if (keylen == 16) cipher = EVP_aes_128_gcm();
    else if (keylen == 24) cipher = EVP_aes_192_gcm();
    else if (keylen == 32) cipher = EVP_aes_256_gcm();
    else { EVP_CIPHER_CTX_free(ctx); return -2; }

    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) { EVP_CIPHER_CTX_free(ctx); return -3; }
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, noncelen, NULL) != 1) { EVP_CIPHER_CTX_free(ctx); return -4; }
    if (EVP_EncryptInit_ex(ctx, NULL, NULL, key, nonce) != 1) { EVP_CIPHER_CTX_free(ctx); return -5; }

    int outl = 0, total = 0;
    if (aadlen > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outl, aad, aadlen) != 1) { EVP_CIPHER_CTX_free(ctx); return -6; }
    }
    if (EVP_EncryptUpdate(ctx, out, &outl, pt, (int)ptlen) != 1) { EVP_CIPHER_CTX_free(ctx); return -7; }
    total = outl;
    if (EVP_EncryptFinal_ex(ctx, out + total, &outl) != 1) { EVP_CIPHER_CTX_free(ctx); return -8; }
    total += outl;
    if (EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag) != 1) { EVP_CIPHER_CTX_free(ctx); return -9; }
    EVP_CIPHER_CTX_free(ctx);
    return total;
}
