#include <Python.h>
#include <openssl/evp.h>
#include <string.h>

static PyObject* fast_encrypt(PyObject* self, PyObject* args) {
    PyObject *key_obj, *nonce_obj, *aad_obj, *pt_obj;
    if (!PyArg_ParseTuple(args, "OOOO", &key_obj, &nonce_obj, &aad_obj, &pt_obj))
        return NULL;

    char *key, *nonce, *aad, *pt;
    Py_ssize_t keylen, noncelen, aadlen, ptlen;
    if (PyBytes_AsStringAndSize(key_obj, &key, &keylen) < 0) return NULL;
    if (PyBytes_AsStringAndSize(nonce_obj, &nonce, &noncelen) < 0) return NULL;
    if (PyBytes_AsStringAndSize(pt_obj, &pt, &ptlen) < 0) return NULL;
    if (aad_obj == Py_None) {
        aad = NULL; aadlen = 0;
    } else {
        if (PyBytes_AsStringAndSize(aad_obj, &aad, &aadlen) < 0) return NULL;
    }

    const EVP_CIPHER *cipher;
    if (keylen == 16) cipher = EVP_aes_128_gcm();
    else if (keylen == 24) cipher = EVP_aes_192_gcm();
    else if (keylen == 32) cipher = EVP_aes_256_gcm();
    else { PyErr_SetString(PyExc_ValueError, "bad key size"); return NULL; }

    EVP_CIPHER_CTX *ctx = EVP_CIPHER_CTX_new();
    if (!ctx) { PyErr_NoMemory(); return NULL; }

    PyObject* ct = PyBytes_FromStringAndSize(NULL, ptlen);
    PyObject* tag = PyBytes_FromStringAndSize(NULL, 16);
    if (!ct || !tag) { Py_XDECREF(ct); Py_XDECREF(tag); EVP_CIPHER_CTX_free(ctx); return NULL; }
    unsigned char *ct_ptr = (unsigned char*)PyBytes_AS_STRING(ct);
    unsigned char *tag_ptr = (unsigned char*)PyBytes_AS_STRING(tag);

    int ok = 1;
    if (EVP_EncryptInit_ex(ctx, cipher, NULL, NULL, NULL) != 1) ok = 0;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_SET_IVLEN, (int)noncelen, NULL) != 1) ok = 0;
    if (ok && EVP_EncryptInit_ex(ctx, NULL, NULL, (unsigned char*)key, (unsigned char*)nonce) != 1) ok = 0;
    int outl = 0, total = 0;
    if (ok && aadlen > 0) {
        if (EVP_EncryptUpdate(ctx, NULL, &outl, (unsigned char*)aad, (int)aadlen) != 1) ok = 0;
    }
    if (ok && EVP_EncryptUpdate(ctx, ct_ptr, &outl, (unsigned char*)pt, (int)ptlen) != 1) ok = 0;
    total = outl;
    if (ok && EVP_EncryptFinal_ex(ctx, ct_ptr + total, &outl) != 1) ok = 0;
    total += outl;
    if (ok && EVP_CIPHER_CTX_ctrl(ctx, EVP_CTRL_GCM_GET_TAG, 16, tag_ptr) != 1) ok = 0;
    EVP_CIPHER_CTX_free(ctx);

    if (!ok) {
        Py_DECREF(ct); Py_DECREF(tag);
        PyErr_SetString(PyExc_RuntimeError, "encryption failed");
        return NULL;
    }
    PyObject* result = PyTuple_Pack(2, ct, tag);
    Py_DECREF(ct); Py_DECREF(tag);
    return result;
}

static PyMethodDef methods[] = {
    {"encrypt", fast_encrypt, METH_VARARGS, "AES-GCM encrypt"},
    {NULL, NULL, 0, NULL}
};

static struct PyModuleDef moduledef = {
    PyModuleDef_HEAD_INIT, "fastgcm", NULL, -1, methods
};

PyMODINIT_FUNC PyInit_fastgcm(void) {
    return PyModule_Create(&moduledef);
}
EOF
